<?php RbacService::authorize('audit.view');$u=AuthService::requireUser();$q=Database::connection()->prepare('SELECT a.*,COALESCE(e.full_name,us.username,\'Sistem\') actor_name FROM audit_logs a LEFT JOIN users us ON us.id=a.actor_user_id LEFT JOIN employees e ON e.id=us.employee_id WHERE a.institution_id=? OR a.institution_id IS NULL ORDER BY a.created_at DESC LIMIT 100');$q->execute([$u['institution_id']]);$logs=$q->fetchAll();$icons=['auth.login'=>'ri-login-box-line','document.created'=>'ri-file-add-line','document.updated'=>'ri-edit-line','document.submitted'=>'ri-send-plane-line','workflow.approved'=>'ri-check-double-line','file.downloaded'=>'ri-download-2-line','document.signed'=>'ri-quill-pen-line']; ?>
<div class="page-shell"><header class="page-header"><div><p class="eyebrow">KEAMANAN & KEPATUHAN</p><h1>Audit Log<span>.</span></h1><p>Jejak aktivitas immutable dari transaksi sistem sebenarnya.</p></div><button class="secondary-button"><i class="ri-download-2-line"></i>Ekspor Log</button></header><section class="panel"><div class="action-bar"><label class="search-field"><i class="ri-search-line"></i><input data-table-search type="search" placeholder="Cari pengguna, aktivitas, atau alamat IP..."></label><select><option>Semua aktivitas</option><option>Autentikasi</option><option>Persetujuan</option></select></div><div class="audit-list"><?php if(!$logs): ?><div class="empty-state"><p>Belum ada aktivitas tercatat.</p></div><?php endif; ?><?php foreach($logs as $l): ?><div data-row class="audit-row"><span class="doc-icon <?= $l['severity']==='critical'?'rose':($l['severity']==='warning'?'amber':'blue') ?>"><i class="<?= $icons[$l['event']]??'ri-history-line' ?>"></i></span><div><strong><?= e($l['description']?:$l['event']) ?></strong><small><?= e($l['actor_name']) ?> · <?= e($l['object_type']?:'sistem') ?></small></div><time><?= e($l['created_at']) ?></time><code><?= e($l['ip_address']?:'-') ?></code></div><?php endforeach; ?></div></section></div>
